    "description": "对于2027年scale-up场景下的产品出货预期，中际旭创7月28日在电话会议上表示，2027年下半年开始，预计行业内有两个有影响力的重点客户开始批量采购NPO产品，更大上量预计会在2028年。目前多家CSP厂商、大模型企业、Neocloud客户均对NPO产品感兴趣，2027年期间有望陆续完成产品导入。NPO有望成为在scale-up场景的主流产品之一，并分阶段放量，首先是头部企业开始采用，随后扩展至更多客户。（证券时报）",
    "content": "对于2027年scale-up场景下的产品出货预期，中际旭创7月28日在电话会议上表示，2027年下半年开始，预计行业内有两个有影响力的重点客户开始批量采购NPO产品，更大上量预计会在2028年。目前多家CSP厂商、大模型企业、Neocloud客户均对NPO产品感兴趣，2027年期间有望陆续完成产品导入。NPO有望成为在scale-up场景的主流产品之一，并分阶段放量，首先是头部企业开始采用，随后扩展至更多客户。（证券时报）"
