    "description": "7月24日，欧盟委员会向TikTok通报初步调查结果：该平台未能按照欧盟《数字服务法》的要求，为未成年人提供足够安全的账户环境。欧盟委员会特别指出，未成年人可以把账户设为公开，16岁至17岁用户发布的内容甚至可能经“为你推荐”信息流推送给任何人。欧盟要求，保护未成年人不能依赖用户主动选择，安全设置应当成为默认选项。",
    "content": "7月24日，欧盟委员会向TikTok通报初步调查结果：该平台未能按照欧盟《数字服务法》的要求，为未成年人提供足够安全的账户环境。欧盟委员会特别指出，未成年人可以把账户设为公开，16岁至17岁用户发布的内容甚至可能经“为你推荐”信息流推送给任何人。欧盟要求，保护未成年人不能依赖用户主动选择，安全设置应当成为默认选项。"
