    "content": "新华社纽约7月28日电（记者刘亚南）美伊暂停互袭令市场对中东地缘冲突的担忧缓解，国际原油期货价格28日上午进一步显著下跌，纽约油价收盘时跌破每桶80美元。 截至当天收盘，纽约商品交易所9月交货的轻质原油期货价格下跌3.35美元，收于每桶79.26美元，跌幅为4.06%；9月交货的伦敦布伦特原油期货价格下跌4.27美元，收于每桶84.09美元，跌幅为4.83%。 特朗普27日对媒体表示，他决定暂停对伊朗的打击，以便给谈判一次机会，但如果外交努力失败，他可能下令恢复实施更大规模的军事行动。同一天，伊朗外交部长阿拉格齐与…"
