    "id": "新闻-36氪-https://36kr.com/newsflashes/3915923736358529?f=rss",
    "feed_name": "36氪",
    "category": "新闻",
    "title": "SK海力士：计划2026年下半年大幅扩充HBM4产能供给",
    "link": "https://36kr.com/newsflashes/3915923736358529?f=rss",
    "pub_date": "2026-07-29 07:23:37",
    "author": "",
    "description": "SK海力士称，计划2026年下半年大幅扩充HBM4产能供给。已与10家行业大客户签订长期芯片供货协议（LTA）；预计2026年三季度DRAM出货量环比二季度提升约10%；预计2026年三季度NAND闪存出货量环比二季度小幅上涨，涨幅为低个位数（1%~4%）；长期供货协议设置差异化定价机制，根据客户类型、芯片产品特性区分定价，平抑存储价格周期性剧烈波动；长期供货协议将显著提升企业中长期订单、需求端的确定性。（财联社）",
