    "description": "美国晶片巨头英伟达掌舵人黄仁勋上周五（7月24日）在社交平台X上发布了“处女帖”，力挺开源人工智能（AI）模型，还附上一封题为《开放权重与美国的AI领导地位》的公开信。和英伟达一起签署这封信的，还有Meta、微软、Palantir等25家美国科技企业与机构。 这封公开信把围绕AI开源的争论，与1980年代开源软件的崛起做比较，指出开放权重模型将允许初创企业、大学和公共机构直接在先进模型基础上进行开发，无须从头训练模型，也无须为每项任务都…",
    "content": "美国晶片巨头英伟达掌舵人黄仁勋上周五（7月24日）在社交平台X上发布了“处女帖”，力挺开源人工智能（AI）模型，还附上一封题为《开放权重与美国的AI领导地位》的公开信。和英伟达一起签署这封信的，还有Meta、微软、Palantir等25家美国科技企业与机构。 这封公开信把围绕AI开源的争论，与1980年代开源软件的崛起做比较，指出开放权重模型将允许初创企业、大学和公共机构直接在先进模型基础上进行开发，无须从头训练模型，也无须为每项任务都支付昂贵的前沿模型使用费，从而能扩大AI经济的参与面。 公开信也认为，这将加强行…"
