    "content": "新华社联合国7月28日电 中国常驻联合国代表团临时代办孙磊28日在联大通过安理会改革政府间谈判过渡决定后发言，指出政府间谈判是讨论安理会改革问题的唯一合法平台。 孙磊说，中方欢迎联大以协商一致方式通过口头决定，将本届联大安理会改革政府间谈判技术性过渡到下届联大。政府间谈判是讨论安理会改革问题的唯一合法平台。安理会改革事关各国重大利益。中方希望各方秉持战略视野和长远眼光，共同维护政府间谈判主渠道地位，坚持会员国共识原则，在政府间谈判继续深入沟通、凝聚共识，确保改革进程朝着提升发展中国家的代表性和发言权的唯一正确方向发…"
