    "content": "28/07/2026 - 21:29 路透社与益普索（Reuters/Ipsos）最新民意调查显示，目前仅有1/3的美国人支持对伊朗战争，这是开战5个月以来最低；近7成受访美国民众表示，总统特朗普未能说清楚他的目标。 该调查在全美网路进行，涵盖1246位美国成年人，抽样误差为正负3个百分点。关于对特朗普的整体支持率，这项在24日至26日所做调查显示，比上月略上升3个百分点，来到37%。在6月下旬调查时，特朗普的支持率曾跌至此任内最低点34%。 自2月28日美国与以色列对伊朗发动空袭以来，目前美国民众对这场战争的支持…"
