    "content": "28/07/2026 - 20:15 美国总统特朗普（Donald Trump）28日在白宫先后与乌克兰总统泽连斯基（Volodymyr Zelensky）及以色列总理内塔尼亚胡（Benjamin Netanyahu）举行会谈，两场会议均已结束。 白宫发言人莱维特（Karoline Leavitt）会后表示：“特朗普总统已完成与泽连斯基总统及内塔尼亚胡总理在椭圆形办公室的会谈。两场会议都积极且富有成效。” 白宫未立即公布两场会谈的详细内容，但根据美方及相关人士透露，特朗普与泽连斯基主要讨论乌克兰战事、防空能力及外交…"
