    "description": "新华社东京7月29日电（记者陈泽安 李子越）据日本共同社报道，熊本县28日发生的强震造成位于八代市的日本制纸集团工厂烟囱倒塌，两名获救人员处于心肺停止状态。 另据日本《朝日新闻》报道，此前有11人被困该工厂，两人获救但处于心肺停止状态，另外9人下落不明。 当地时间16时27分（北京时间15时27分）许，熊本县发生7.1级地震，震中位于北纬32.6度、东经130.7度，震源深度约10公里。地震已造成数十人伤亡。",
    "content": "新华社东京7月29日电（记者陈泽安 李子越）据日本共同社报道，熊本县28日发生的强震造成位于八代市的日本制纸集团工厂烟囱倒塌，两名获救人员处于心肺停止状态。 另据日本《朝日新闻》报道，此前有11人被困该工厂，两人获救但处于心肺停止状态，另外9人下落不明。 当地时间16时27分（北京时间15时27分）许，熊本县发生7.1级地震，震中位于北纬32.6度、东经130.7度，震源深度约10公里。地震已造成数十人伤亡。"
