    "description": "",
    "content": "快科技7月29日消息，66岁加拿大男子阿夫塔尔·辛格耗费数十年寻找亲生母亲，动用档案库、社交平台、私家侦探多方渠道都一无所获。 濒临绝望之际，他抱着试试看的心态向AI输入零散记忆线索，竟成功串联关键信息，找到失散半个世纪的母亲与同父异母的妹妹。 阿夫塔尔出生于上世纪60年代印度阿姆利则，自幼由爷爷奶奶抚养长大，八岁那年才得知抚养他长大的并非生母，亲生母亲萨温德当年远赴英国生活，生父则前往加拿大任教，寻母成了他大半辈子的心结。 数十年间，阿夫塔尔投入大量时间、金钱四处打探，翻阅印度、英国、加拿大三国老旧户籍档案，在脸…"
