    "content": "快科技7月29日消息，日前， 39岁美国男子凯·佐藤独自驾帆船横渡太平洋时遭遇连环故障，船只桅杆断裂、燃油与导航设备全部失效，在海上孤立漂流整整30天，最终被过路货轮意外救下 。 上月7日，佐藤从加州卡特琳娜岛出发，计划完成人生首次单人跨太平洋航行，航行两周后，海上狂风巨浪直接折断帆船主桅杆，船只彻底失去依靠风帆航行的能力。 他立刻启动发动机试图折返海岸，可燃油很快彻底耗尽，用来定位导航的手机也因断电彻底失灵，小船彻底失去操控，只能顺着洋流一路向南漂流，航线大幅偏离原定路线。 绝境之下佐藤一度陷入重度绝望，他坦言自…"
