    "content": "上篇： 自建 NetBird 稳定吗？ 前情回顾：WireGuard 不够方便，于是我自建了 NetBird 。 WireGuard 的问题： 公钥得手动分发 DDNS 支持不够好（只在建立连接时解析一次域名，后续 IP 更新感知不到） NetBird 整体给我的感觉都不错（到现在也是），但是目前还是发现两个问题： 一个是 NetBird 的手机客户端好像没跟上版本，很古老 一个是自建 NetBird 中招了 Next.js 的漏洞，而自建 BUG 修复没有官方那么及时 因此，后续在跟 AI 迭代几轮后，我还是选择…"
