    "content": "新华社东京7月28日电（记者李子越 陈泽安）日本熊本县28日发生7.1级地震。据日本媒体报道，地震已造成当地大量人员受伤，目前已确认有数人死亡，多处房屋倒塌，设施受损，交通严重受阻。 据报道，地震发生后，当地余震不断。日本气象厅数据显示，截至当地时间28日23时，震区已发生数十次余震，截至发稿时，余震仍未停止。 人员伤亡方面，熊本县八代市一人在倒塌房屋内被发现，送医后确认死亡。熊本县嘉岛町因地震而爆炸坍塌的商场内，有20至30名员工下落不明，随后警方确认有数人死亡。日本共同社28日晚引述熊本县警方消息称，由于存在发…"
