    "description": "新华社北京7月28日电（记者尚昊）“我们香港青少年，从航天员们身上学习到了‘特别能吃苦、特别能战斗、特别能攻关、特别能奉献’的载人航天精神，希望表达我们对中国航天事业筚路蓝缕70年的敬意，同时表达我们渴望为国家航天事业增添香港力量的愿望。”28日下午，在中国宋庆龄青少年科技文化交流中心，香港九龙真光中学学生们的诚挚分享，赢得了在场人士的阵阵掌声。 当天，“缔造未来”青少年创新发展项目之新时代筑梦计划新能源、航空航天及工程技术主题深度创科…",
    "content": "新华社北京7月28日电（记者尚昊）“我们香港青少年，从航天员们身上学习到了‘特别能吃苦、特别能战斗、特别能攻关、特别能奉献’的载人航天精神，希望表达我们对中国航天事业筚路蓝缕70年的敬意，同时表达我们渴望为国家航天事业增添香港力量的愿望。”28日下午，在中国宋庆龄青少年科技文化交流中心，香港九龙真光中学学生们的诚挚分享，赢得了在场人士的阵阵掌声。 当天，“缔造未来”青少年创新发展项目之新时代筑梦计划新能源、航空航天及工程技术主题深度创科实践训练营结营仪式在京举行。 仪式现场，一件件充满巧思的创科实践作品令人眼前一亮…"
