    "content": "新华社南宁7月28日电（记者梁雨浪）记者28日从广西壮族自治区人民政府新闻办公室举办的新闻发布会获悉，今年以来，面对地震、洪涝等严重灾害，广西在资金汇划、保险保障、信贷资源等方面持续开展金融支持防灾救灾和灾后重建工作。 据介绍，截至7月24日，广西累计拨付国库专项救灾应急资金超5亿元，紧急调度支农支小再贷款29.63亿元。全区保险业累计为地震、暴雨、台风等灾害赔付超15亿元。其中，为柳州地震灾害赔付2.53亿元，含巨灾民生综合保险赔付2.52亿元；对近期台风“美莎克”造成南宁横州、贵港、钦州等地洪涝灾害已赔付11.…"
