    "author": "庞昕熠,王卓伦",
    "description": "新华社耶路撒冷7月28日电（记者庞昕熠 王卓伦）以色列国防部长卡茨28日发表声明称，他已指示以军扩大在约旦河西岸的军事行动，并准备接管一处巴勒斯坦难民营并强行疏散那里的居民。 声明未提及这处难民营的具体信息，但称“接管行动”将与此前以色列国防军对杰宁、图勒凯尔姆和努尔沙姆斯难民营采取的行动类似，即强行疏散居民、清除武装基础设施，并由以军长期驻守。 卡茨当天在接受以色列第14频道电视台采访时说，以色列计划扩大约旦河西岸的犹太人定居点规模，…",
    "content": "新华社耶路撒冷7月28日电（记者庞昕熠 王卓伦）以色列国防部长卡茨28日发表声明称，他已指示以军扩大在约旦河西岸的军事行动，并准备接管一处巴勒斯坦难民营并强行疏散那里的居民。 声明未提及这处难民营的具体信息，但称“接管行动”将与此前以色列国防军对杰宁、图勒凯尔姆和努尔沙姆斯难民营采取的行动类似，即强行疏散居民、清除武装基础设施，并由以军长期驻守。 卡茨当天在接受以色列第14频道电视台采访时说，以色列计划扩大约旦河西岸的犹太人定居点规模，将新建数十个定居点。他还表示，以军不会撤出目前在加沙地带、叙利亚和黎巴嫩控制的地…"
