    "content": "新华社北京7月28日电（记者董雪）中共中央政治局委员、外交部长王毅28日在北京出席全球发展倡议5周年高级别会议并致辞。 王毅表示，5年前，面对全球发展事业何去何从的时代之问，习近平主席郑重提出全球发展倡议，为重振全球发展事业提供了中国方案、作出了中国贡献。5年来，倡议的理念引领效应持续释放，各领域合作机制不断完善，务实合作成果接连落地。当前国际形势变乱交织，全球发展倡议的时代意义更加凸显。我们要继续高举发展旗帜，坚定推进全球发展倡议与联合国发展议程对接。一是加强团结合作，营造和平发展环境；二是凝聚行动合力，加快落实…"
