    "content": "新华社德黑兰7月28日电（记者陈霄 沙达提）据伊朗伊斯兰共和国广播电视台28日报道，伊朗武装部队哈塔姆安比亚中央总部发言人说，接受美国使用伊朗资产进行所谓赔偿的任何国家或公司，其所属船只将不被允许通过霍尔木兹海峡。 发言人说，美国总统特朗普此前宣布，将利用伊朗被冻结资产，赔偿伊美冲突期间受损船只。伊方认为，这些船只受损是由于美军制造地区不安全局势，以及“违规驶入霍尔木兹海峡南部非法且不安全的航道”所致。他警告称，自即日起，任何支持特朗普上述提议和使用伊朗被冻结资产的国家或公司所属船只将被禁止通过霍尔木兹海峡。 特朗…"
