    "title": "特朗普再次威胁打击伊朗镐山地下核设施",
    "link": "http://www.news.cn/20260728/f05571c54fc2403b97a11e2b5b752474/c.html",
    "pub_date": "2026-07-28 21:47:35",
    "author": "郭文迪",
    "description": "新华社华盛顿7月28日电 美国总统特朗普28日再次威胁称，如果美国和伊朗无法达成协议，美国将打击伊朗镐山地下核设施。 特朗普在接受美国福克斯新闻频道采访时说：“我们用世界上最好的摄像机对准了那里……我非常清楚镐山的情况，那不是什么大问题。”他说，如果美伊达不成协议，就必须摧毁镐山。 特朗普曾于21日对媒体说，美国“可能很快”打击伊朗镐山地下核设施。 镐山位于伊朗中部伊斯法罕省纳坦兹核设施附近，被认为是伊朗最坚固的地下核设施之一。",
    "content": "新华社华盛顿7月28日电 美国总统特朗普28日再次威胁称，如果美国和伊朗无法达成协议，美国将打击伊朗镐山地下核设施。 特朗普在接受美国福克斯新闻频道采访时说：“我们用世界上最好的摄像机对准了那里……我非常清楚镐山的情况，那不是什么大问题。”他说，如果美伊达不成协议，就必须摧毁镐山。 特朗普曾于21日对媒体说，美国“可能很快”打击伊朗镐山地下核设施。 镐山位于伊朗中部伊斯法罕省纳坦兹核设施附近，被认为是伊朗最坚固的地下核设施之一。"
